window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6d46418f455220ec"]={"versions": [{"id": "FIG-6d46418f455220ec", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Schnittstellendiagramm im architektonischen Kontext der AUTOSAR Adaptive Platform (EXP_SWArchitecture). Das Diagramm spezifiziert die von dem Functional Cluster <em>Vehicle Update and Configuration Management</em> (VUCM) benötigten Schnittstellen (<em>required ports</em>) zu den Funktionsclustern <em>Time Synchronization</em> und <em>Persistency</em>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Functional Cluster und drei Port-Interfaces:</p>\n<ol class=\"fig-list\">\n<li><strong>Functional Cluster</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>«aapFunctionalCluster» Vehicle Update and Configuration Management</code> (daemon-based, oben dargestellt, orange hinterlegt).</li>\n<li><code>«aapFunctionalCluster» Time Synchronization</code> (daemon-based, unten links dargestellt, blau hinterlegt).</li>\n<li><code>«aapFunctionalCluster» Persistency</code> (unten rechts dargestellt, grün hinterlegt).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schnittstellen (<code>«aapAPI,aapPortInterface»</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>SynchronizedTimeBaseConsumer</code>: Bereitgestellt von <em>Time Synchronization</em> (Realisierungspfeil), genutzt von <em>Vehicle Update and Configuration Management</em> über einen Required Port (<code>«use» «aapRequiredPort»</code>). Methoden:</li>\n<li><code>+ GetCurrentTime()</code></li>\n<li><code>+ GetRateDeviation()</code></li>\n<li><code>+ GetTimeWithStatus(): SynchronizedTimeBaseStatus</code></li>\n<li><code>+ RegisterStatusChangeNotifier()</code></li>\n<li><code>+ RegisterSynchronizationStateChangeNotifier()</code></li>\n<li><code>+ RegisterTimeLeapNotifier()</code></li>\n<li><code>+ RegisterTimePrecisionMeasurementNotifier()</code></li>\n<li><code>+ RegisterTimeValidationNotification()</code></li>\n<li><code>+ UnregisterStatusChangeNotifier()</code></li>\n<li><code>+ UnregisterSynchronizationStateChangeNotifier()</code></li>\n<li><code>+ UnregisterTimeLeapNotifier()</code></li>\n<li><code>+ UnregisterTimePrecisionMeasurementNotifier()</code></li>\n<li><code>+ UnregisterTimeValidationNotification()</code></li>\n<li><code>FileStorage</code>: Bereitgestellt von <em>Persistency</em> (Realisierungspfeil), genutzt von <em>Vehicle Update and Configuration Management</em> über einen Required Port (<code>«use» «aapRequiredPort»</code>). Methoden:</li>\n<li><code>+ DeleteFile()</code></li>\n<li><code>+ FileExists()</code></li>\n<li><code>+ GetAllFileNames()</code></li>\n<li><code>+ GetCurrentFileSize()</code></li>\n<li><code>+ GetFileInfo()</code></li>\n<li><code>+ OpenFileReadOnly(): ReadAccessor</code></li>\n<li><code>+ OpenFileReadWrite(): ReadWriteAccessor</code></li>\n<li><code>+ OpenFileWriteOnly(): ReadWriteAccessor</code></li>\n<li><code>+ RecoverFile()</code></li>\n<li><code>+ ResetFile()</code></li>\n<li><code>KeyValueStorage</code>: Bereitgestellt von <em>Persistency</em> (Realisierungspfeil), genutzt von <em>Vehicle Update and Configuration Management</em> über einen Required Port (<code>«use» «aapRequiredPort»</code>). Methoden:</li>\n<li><code>+ DiscardPendingChanges()</code></li>\n<li><code>+ GetAllKeys()</code></li>\n<li><code>+ GetValue()</code></li>\n<li><code>+ KeyExists()</code></li>\n<li><code>+ RecoverKey()</code></li>\n<li><code>+ RemoveAllKeys()</code></li>\n<li><code>+ RemoveKey()</code></li>\n<li><code>+ ResetKey()</code></li>\n<li><code>+ SetValue()</code></li>\n<li><code>+ SyncToStorage()</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Deklaration von Port-Interfaces und Abhängigkeiten; kein dynamischer Sequenzablauf im Diagramm dargestellt. Zur Laufzeit konsumiert der VUCM-Daemon Zeitsynchronisationsdienste (Abfrage synchronisierter Zeitbasen, Statusabfragen und Callback-Registrierungen für Zeitsprünge oder Genauigkeitsänderungen) sowie Persistenzdienste für strukturierte Schlüssel-Wert-Paare und dateibasierte Speicherung (Lesen, Schreiben, Wiederherstellen von Dateien).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der C++-API- und Port-Interface-Signaturen für Applikations- und Cluster-Interaktionen auf der Adaptive Platform:</p>\n<ul class=\"fig-list\">\n<li>VUCM erfordert die Einbindung von Persistency (<code>FileStorage</code>, <code>KeyValueStorage</code>) und Time Synchronization (<code>SynchronizedTimeBaseConsumer</code>).</li>\n<li>Persistency-Zugriff erfolgt über typisierte Accessor-Klassen (<code>ReadAccessor</code>, <code>ReadWriteAccessor</code>).</li>\n<li>Benachrichtigungsmechanismen basieren auf expliziter Registrierung/Deregistrierung von Notifier-Callbacks für Status- und Zeitsprung-Ereignisse.</li>\n</ul>"}, {"id": "FIG-b1176358c0c3e9cb", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Schnittstellendiagramm im architektonischen Kontext der AUTOSAR Adaptive Platform (EXP_SWArchitecture). Das Diagramm spezifiziert die von dem Functional Cluster <em>Vehicle Update and Configuration Management</em> (VUCM) benötigten Schnittstellen (<em>required ports</em>) zu den Funktionsclustern <em>Time Synchronization</em> und <em>Persistency</em>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Functional Cluster und drei Port-Interfaces:</p>\n<ol class=\"fig-list\">\n<li><strong>Functional Cluster</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>«aapFunctionalCluster» Vehicle Update and Configuration Management</code> (daemon-based, oben dargestellt, orange hinterlegt).</li>\n<li><code>«aapFunctionalCluster» Time Synchronization</code> (daemon-based, unten links dargestellt, blau hinterlegt).</li>\n<li><code>«aapFunctionalCluster» Persistency</code> (unten rechts dargestellt, grün hinterlegt).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schnittstellen (<code>«aapAPI,aapPortInterface»</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>SynchronizedTimeBaseConsumer</code>: Bereitgestellt von <em>Time Synchronization</em> (Realisierungspfeil), genutzt von <em>Vehicle Update and Configuration Management</em> über einen Required Port (<code>«use» «aapRequiredPort»</code>). Methoden:</li>\n<li><code>+ GetRateDeviation()</code></li>\n<li><code>+ GetTimeWithStatus(): SynchronizedTimeBaseStatus</code></li>\n<li><code>+ RegisterStatusChangeNotifier()</code></li>\n<li><code>+ RegisterSynchronizationStateChangeNotifier()</code></li>\n<li><code>+ RegisterTimeLeapNotifier()</code></li>\n<li><code>+ RegisterTimePrecisionMeasurementNotifier()</code></li>\n<li><code>+ RegisterTimeValidationNotification()</code></li>\n<li><code>+ UnregisterStatusChangeNotifier()</code></li>\n<li><code>+ UnregisterSynchronizationStateChangeNotifier()</code></li>\n<li><code>+ UnregisterTimeLeapNotifier()</code></li>\n<li><code>+ UnregisterTimePrecisionMeasurementNotifier()</code></li>\n<li><code>+ UnregisterTimeValidationNotification()</code></li>\n<li><code>FileStorage</code>: Bereitgestellt von <em>Persistency</em> (Realisierungspfeil), genutzt von <em>Vehicle Update and Configuration Management</em> über einen Required Port (<code>«use» «aapRequiredPort»</code>). Methoden:</li>\n<li><code>+ DeleteFile()</code></li>\n<li><code>+ FileExists()</code></li>\n<li><code>+ GetAllFileNames()</code></li>\n<li><code>+ GetCurrentFileSize()</code></li>\n<li><code>+ GetFileInfo()</code></li>\n<li><code>+ OpenFileReadOnly(): ReadAccessor</code></li>\n<li><code>+ OpenFileReadWrite(): ReadWriteAccessor</code></li>\n<li><code>+ OpenFileWriteOnly(): ReadWriteAccessor</code></li>\n<li><code>+ RecoverFile()</code></li>\n<li><code>+ ResetFile()</code></li>\n<li><code>KeyValueStorage</code>: Bereitgestellt von <em>Persistency</em> (Realisierungspfeil), genutzt von <em>Vehicle Update and Configuration Management</em> über einen Required Port (<code>«use» «aapRequiredPort»</code>). Methoden:</li>\n<li><code>+ DiscardPendingChanges()</code></li>\n<li><code>+ GetAllKeys()</code></li>\n<li><code>+ GetCurrentValueSize()</code></li>\n<li><code>+ GetValue()</code></li>\n<li><code>+ KeyExists()</code></li>\n<li><code>+ RecoverKey()</code></li>\n<li><code>+ RemoveAllKeys()</code></li>\n<li><code>+ RemoveKey()</code></li>\n<li><code>+ ResetKey()</code></li>\n<li><code>+ SetValue()</code></li>\n<li><code>+ SyncToStorage()</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Deklaration von Port-Interfaces und Abhängigkeiten; kein dynamischer Sequenzablauf im Diagramm dargestellt. Zur Laufzeit konsumiert der VUCM-Daemon Zeitsynchronisationsdienste (Abfrage synchronisierter Zeitbasen, Statusabfragen und Callback-Registrierungen für Zeitsprünge oder Genauigkeitsänderungen) sowie Persistenzdienste für strukturierte Schlüssel-Wert-Paare und dateibasierte Speicherung (Lesen, Schreiben, Wiederherstellen von Dateien).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der C++-API- und Port-Interface-Signaturen für Applikations- und Cluster-Interaktionen auf der Adaptive Platform:</p>\n<ul class=\"fig-list\">\n<li>VUCM erfordert die Einbindung von Persistency (<code>FileStorage</code>, <code>KeyValueStorage</code>) und Time Synchronization (<code>SynchronizedTimeBaseConsumer</code>).</li>\n<li>Persistency-Zugriff erfolgt über typisierte Accessor-Klassen (<code>ReadAccessor</code>, <code>ReadWriteAccessor</code>).</li>\n<li>Benachrichtigungsmechanismen basieren auf expliziter Registrierung/Deregistrierung von Notifier-Callbacks für Status- und Zeitsprung-Ereignisse.</li>\n</ul>"}, {"id": "FIG-2c3c9fb4b691bf59", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Schnittstellendiagramm im architektonischen Kontext der AUTOSAR Adaptive Platform (EXP_SWArchitecture). Das Diagramm spezifiziert die von dem Functional Cluster <em>Vehicle Update and Configuration Management</em> (VUCM) benötigten Schnittstellen (<em>required ports</em>) zu den Funktionsclustern <em>Time Synchronization</em> und <em>Persistency</em>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Functional Cluster und drei Port-Interfaces:</p>\n<ol class=\"fig-list\">\n<li><strong>Functional Cluster</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>«aapFunctionalCluster» Vehicle Update and Configuration Management</code> (daemon-based, oben dargestellt, orange hinterlegt).</li>\n<li><code>«aapFunctionalCluster» Time Synchronization</code> (daemon-based, unten links dargestellt, blau hinterlegt).</li>\n<li><code>«aapFunctionalCluster» Persistency</code> (unten rechts dargestellt, grün hinterlegt).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schnittstellen (<code>«aapAPI,aapPortInterface»</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>SynchronizedTimeBaseConsumer</code>: Bereitgestellt von <em>Time Synchronization</em> (Realisierungspfeil), genutzt von <em>Vehicle Update and Configuration Management</em> über einen Required Port (<code>«use» «aapRequiredPort»</code>). Methoden:</li>\n<li><code>+ GetRateDeviation()</code></li>\n<li><code>+ GetTimeWithStatus(): SynchronizedTimeBaseStatus</code></li>\n<li><code>+ RegisterStatusChangeNotifier()</code></li>\n<li><code>+ RegisterSynchronizationStateChangeNotifier()</code></li>\n<li><code>+ RegisterTimeLeapNotifier()</code></li>\n<li><code>+ RegisterTimePrecisionMeasurementNotifier()</code></li>\n<li><code>+ RegisterTimeValidationNotification()</code></li>\n<li><code>+ UnregisterStatusChangeNotifier()</code></li>\n<li><code>+ UnregisterSynchronizationStateChangeNotifier()</code></li>\n<li><code>+ UnregisterTimeLeapNotifier()</code></li>\n<li><code>+ UnregisterTimePrecisionMeasurementNotifier()</code></li>\n<li><code>+ UnregisterTimeValidationNotification()</code></li>\n<li><code>FileStorage</code>: Bereitgestellt von <em>Persistency</em> (Realisierungspfeil), genutzt von <em>Vehicle Update and Configuration Management</em> über einen Required Port (<code>«use» «aapRequiredPort»</code>). Methoden:</li>\n<li><code>+ DeleteFile()</code></li>\n<li><code>+ FileExists()</code></li>\n<li><code>+ GetAllFileNames()</code></li>\n<li><code>+ GetCurrentFileSize()</code></li>\n<li><code>+ GetFileInfo()</code></li>\n<li><code>+ OpenFileReadOnly(): ReadAccessor</code></li>\n<li><code>+ OpenFileReadWrite(): ReadWriteAccessor</code></li>\n<li><code>+ OpenFileWriteOnly(): WriteAccessor</code></li>\n<li><code>+ RecoverFile()</code></li>\n<li><code>+ ResetFile()</code></li>\n<li><code>KeyValueStorage</code>: Bereitgestellt von <em>Persistency</em> (Realisierungspfeil), genutzt von <em>Vehicle Update and Configuration Management</em> über einen Required Port (<code>«use» «aapRequiredPort»</code>). Methoden:</li>\n<li><code>+ DiscardPendingChanges()</code></li>\n<li><code>+ GetAllKeys()</code></li>\n<li><code>+ GetCurrentValueSize()</code></li>\n<li><code>+ GetValue()</code></li>\n<li><code>+ KeyExists()</code></li>\n<li><code>+ RecoverKey()</code></li>\n<li><code>+ RemoveAllKeys()</code></li>\n<li><code>+ RemoveKey()</code></li>\n<li><code>+ ResetKey()</code></li>\n<li><code>+ SetValue()</code></li>\n<li><code>+ SyncToStorage()</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Deklaration von Port-Interfaces und Abhängigkeiten; kein dynamischer Sequenzablauf im Diagramm dargestellt. Zur Laufzeit konsumiert der VUCM-Daemon Zeitsynchronisationsdienste (Abfrage synchronisierter Zeitbasen, Statusabfragen und Callback-Registrierungen für Zeitsprünge oder Genauigkeitsänderungen) sowie Persistenzdienste für strukturierte Schlüssel-Wert-Paare und dateibasierte Speicherung (Lesen, Schreiben, Wiederherstellen von Dateien).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der C++-API- und Port-Interface-Signaturen für Applikations- und Cluster-Interaktionen auf der Adaptive Platform:</p>\n<ul class=\"fig-list\">\n<li>VUCM erfordert die Einbindung von Persistency (<code>FileStorage</code>, <code>KeyValueStorage</code>) und Time Synchronization (<code>SynchronizedTimeBaseConsumer</code>).</li>\n<li>Persistency-Zugriff erfolgt über typisierte Accessor-Klassen (<code>ReadAccessor</code>, <code>ReadWriteAccessor</code>, <code>WriteAccessor</code>), wobei <code>OpenFileWriteOnly()</code> strikt auf <code>WriteAccessor</code> typisiert ist.</li>\n<li>Benachrichtigungsmechanismen basieren auf expliziter Registrierung/Deregistrierung von Notifier-Callbacks für Status- und Zeitsprung-Ereignisse.</li>\n</ul>"}], "trans": [{"from": "FIG-6d46418f455220ec", "to": "FIG-b1176358c0c3e9cb", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>In <code>SynchronizedTimeBaseConsumer</code> (<code>Time Synchronization</code>) entfällt die Methode <code>+ GetCurrentTime()</code>.</li>\n<li>In <code>KeyValueStorage</code> (<code>Persistency</code>) wird die Methode <code>+ GetCurrentValueSize()</code> ergänzt.</li>\n<li>Keine sonstigen Änderungen an Schnittstellenbeziehungen oder Cluster-Definitionen.</li>\n</ul>"}, {"from": "FIG-b1176358c0c3e9cb", "to": "FIG-2c3c9fb4b691bf59", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>In <code>FileStorage</code> (<code>Persistency</code>) ändert sich der Rückgabetyp der Operation <code>+ OpenFileWriteOnly()</code> von <code>ReadWriteAccessor</code> zu <code>WriteAccessor</code>.</li>\n</ul>"}]};
